Definition gfa_Q : machine_state -> Prop :=
  gfa_ret_post ra sp gp tp s0o s1o s2o s3o s4o s5o s6o s7o s8o s9o s10o s11o F fc R CH n (dest ws chs nfree' (Z.to_nat n))
